// Sculpted Articulated Shadow Thief & Museum Lantern Guard exported from Blender 5.2 LTS.
// Thief: 1862 verts, 3592 tris (6 parts: hooded cloak+belt, head+goggles, L/R legs, L/R arms)
// Guard: 1522 verts, 2912 tris (6 parts: armored tunic+pauldrons, helmet+plume, L/R legs, L/R arms+lantern+halberd)

const THIEF_V = "";
const THIEF_I = "";
const GUARD_V = "";
const GUARD_I = "";

function decodeBase64(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function unpackMesh(vB64, iB64) {
  const vb = decodeBase64(vB64);
  const ib = decodeBase64(iB64);
  const dv = new DataView(vb.buffer, vb.byteOffset, vb.byteLength);
  const nVerts = vb.byteLength / 14;
  // Unpack into Float32Array stride 11: px,py,pz, nx,ny,nz, r,g,b, rough, partId
  const verts = new Float32Array(nVerts * 11);
  for (let i = 0; i < nVerts; i++) {
    const o = i * 14;
    const d = i * 11;
    verts[d + 0] = dv.getInt16(o + 0, true) / 1000;
    verts[d + 1] = dv.getInt16(o + 2, true) / 1000;
    verts[d + 2] = dv.getInt16(o + 4, true) / 1000;
    verts[d + 3] = dv.getInt8(o + 6) / 127;
    verts[d + 4] = dv.getInt8(o + 7) / 127;
    verts[d + 5] = dv.getInt8(o + 8) / 127;
    verts[d + 10] = dv.getUint8(o + 9);
    verts[d + 6] = dv.getUint8(o + 10) / 255;
    verts[d + 7] = dv.getUint8(o + 11) / 255;
    verts[d + 8] = dv.getUint8(o + 12) / 255;
    verts[d + 9] = dv.getUint8(o + 13) / 255;
  }
  const indices = new Uint16Array(ib.buffer, ib.byteOffset, ib.byteLength / 2);
  return { verts, indices, vertCount: nVerts, triCount: indices.length / 3 };
}

let cached = null;
export function getStealthMeshes() {
  if (!cached) {
    cached = {
      thief: unpackMesh(THIEF_V, THIEF_I),
      guard: unpackMesh(GUARD_V, GUARD_I),
    };
  }
  return cached;
}
